<template>
  <div class="hca-root">
    <!-- ── HERO ──────────────────────────────────────────────────────────── -->
    <div class="hca-hero">
      <div class="hca-hero__left">
        <div class="hca-hero__icon">
          <v-icon color="white" size="22">mdi-account-search</v-icon>
        </div>
        <div>
          <div class="hca-hero__title">HR Coverage Audit</div>
          <div class="hca-hero__sub">
            Review which HR officer services each facility and identify
            misconfigured assignments
          </div>
        </div>
      </div>
      <div class="hca-hero__stat" v-if="!loading">
        <div class="hca-hero__stat-val">{{ totalItems }}</div>
        <div class="hca-hero__stat-lbl">Facilities</div>
      </div>
    </div>

    <!-- ── FILTER BAR ─────────────────────────────────────────────────────── -->
    <v-card class="hca-filter-card" flat>
      <v-card-text class="py-3 px-4">
        <v-row dense align="center">
          <!-- Facility name search -->
          <v-col cols="12" sm="6" md="3">
            <v-text-field
              v-model="filters.facilityName"
              label="Search Facility"
              dense
              outlined
              clearable
              hide-details
              prepend-inner-icon="mdi-hospital-building"
              @input="debouncedFetch"
            />
          </v-col>

          <!-- HR facility treeview picker (facility-only selection) -->
          <v-col cols="12" sm="6" md="3">
            <v-menu
              v-model="reportingtoFacilityMenuOpen"
              :close-on-content-click="false"
              offset-y
              min-width="300px"
            >
              <template v-slot:activator="{ on }">
                <v-text-field
                  :value="reportingtoFacilityTree.displayValue"
                  label="Filter by Reporting Facility"
                  dense
                  outlined
                  clearable
                  hide-details
                  readonly
                  prepend-inner-icon="mdi-account-tie"
                  v-on="on"
                  @click:clear="clearreportingtoFacilityTree"
                />
              </template>
              <v-card class="hca-tree-card">
                <v-progress-linear
                  v-if="reportingtoFacilityTree.loading"
                  indeterminate
                  color="primary"
                  height="2"
                />
                <v-treeview
                  :active.sync="reportingtoFacilityTree.active"
                  :items="reportingtoFacilityTree.items"
                  :load-children="fetchHrFacilityChildren"
                  :open.sync="reportingtoFacilityTree.open"
                  :item-disabled="'disabled'"
                  activatable
                  :multiple-active="false"
                  selection-type="independent"
                  item-key="id"
                  dense
                  hoverable
                >
                  <template v-slot:label="{ item }">
                    <div class="hca-tree-label-row">
                      <v-icon
                        size="13"
                        class="hca-tree-icon"
                        :color="reportingtoFacilityNodeColor(item.id)"
