                        {{ reportingtoFacilityNodeIcon(item.id) }}
                      </v-icon>
                      <span class="hca-tree-label">{{ item.name }}</span>
                    </div>
                  </template>
                </v-treeview>
              </v-card>
            </v-menu>
          </v-col>

          <!-- Facility type -->
          <v-col cols="12" sm="6" md="2">
            <v-autocomplete
              v-model="filters.type"
              :items="typeOptions"
              item-text="display"
              item-value="code"
              label="Facility Type"
              dense
              outlined
              clearable
              hide-details
              @change="resetAndFetch"
            />
          </v-col>

          <!-- Status -->
          <v-col cols="12" sm="6" md="2">
            <v-autocomplete
              v-model="filters.status"
              :items="statusOptions"
              item-text="display"
              item-value="code"
              label="Status"
              dense
              outlined
              clearable
