            />
          </v-col>

          <!-- District treeview picker -->
          <v-col cols="12" md="2">
            <v-menu
              v-model="locationMenuOpen"
              :close-on-content-click="false"
              offset-y
              min-width="300px"
            >
              <template v-slot:activator="{ on }">
                <v-text-field
                  :value="locationTree.displayValue"
                  label="Filter by Location"
                  dense
                  outlined
                  clearable
                  hide-details
                  readonly
                  prepend-inner-icon="mdi-map-marker-outline"
                  v-on="on"
                  @click:clear="clearLocationTree"
                />
              </template>
              <v-card class="hca-tree-card">
                <v-progress-linear
                  v-if="locationTree.loading"
                  indeterminate
                  color="primary"
                  height="2"
                />
                <v-treeview
                  :active.sync="locationTree.active"
                  :items="locationTree.items"
                  :load-children="fetchLocationChildren"
                  :open.sync="locationTree.open"
                  activatable
                  :multiple-active="false"
                  selection-type="independent"
                  item-key="id"
                  dense
                  hoverable
                >
                  <template v-slot:label="{ item }">
                    <div class="hca-tree-label-row">
                      <v-icon
                        size="13"
                        class="hca-tree-icon"
                        :color="
                          locationTree.treeLookup[item.id].type === 'district'
                            ? '#1e40af'
                            : locationTree.treeLookup[item.id].type ===
                              'council'
                            ? '#0e7490'
                            : '#a8a29e'
                        "
                      >
                        {{
                          locationTree.treeLookup[item.id].type === "district"
                            ? "mdi-map-marker-radius"
                            : locationTree.treeLookup[item.id].type ===
                              "council"
                            ? "mdi-city"
                            : "mdi-hospital-building"
                        }}
                      </v-icon>
                      <span class="hca-tree-label">{{ item.name }}</span>
                    </div>
                  </template>
                </v-treeview>
              </v-card>
            </v-menu>
          </v-col>
        </v-row>

        <!-- Active filter chips -->
        <div v-if="activeFilterCount > 0" class="hca-chips mt-2">
          <v-chip
            v-if="filters.facilityName"
            x-small
            close
            class="hca-chip"
            @click:close="
              filters.facilityName = null;
              resetAndFetch();
            "
          >
            <v-icon x-small left>mdi-hospital-building</v-icon>
            {{ filters.facilityName }}
          </v-chip>
          <v-chip
            v-if="reportingtoFacilityTree.displayValue"
            x-small
            close
            class="hca-chip"
            @click:close="clearreportingtoFacilityTree"
          >
            <v-icon x-small left>mdi-account-tie</v-icon>
            HR Facility: {{ reportingtoFacilityTree.displayValue }}
          </v-chip>
          <v-chip
            v-if="filters.type"
            x-small
            close
            class="hca-chip"
            @click:close="
              filters.type = null;
              resetAndFetch();
            "
          >
            {{ filters.type }}
          </v-chip>
          <v-chip
            v-if="filters.status"
            x-small
            close
            class="hca-chip"
            @click:close="
              filters.status = null;
              resetAndFetch();
            "
          >
            {{ filters.status }}
          </v-chip>
          <v-chip
            v-if="locationTree.displayValue"
            x-small
            close
            class="hca-chip"
            @click:close="clearLocationTree"
          >
            <v-icon x-small left>mdi-map-marker-outline</v-icon>
            {{ locationTree.displayValue }}
          </v-chip>
          <v-btn
            x-small
            text
            color="grey"
            class="ml-1"
            @click="clearAllFilters"
          >
            Clear all
          </v-btn>
        </div>
      </v-card-text>
    </v-card>

    <!-- ── DATA TABLE ─────────────────────────────────────────────────────── -->
    <v-card class="hca-table-card mt-3" flat>
      <v-data-table
        :headers="headers"
        :items="items"
        :loading="loading"
        :server-items-length="totalItems"
        :options.sync="tableOptions"
        :footer-props="{ 'items-per-page-options': [10, 20, 50] }"
        item-key="facilityId"
        class="hca-table"
      >
        <!-- Loading slot -->
        <template v-slot:progress>
          <v-progress-linear indeterminate color="primary" height="2" />
        </template>

        <!-- Facility name -->
        <template v-slot:item.facilityName="{ item }">
          <div class="hca-facility-cell">
            <span class="hca-bold">{{ item.facilityName }}</span>
            <div class="hca-breadcrumb">
              <span>{{ item.councilName }}</span>
              <v-icon size="10" color="#a8a29e">mdi-chevron-right</v-icon>
              <span>{{ item.districtName }}</span>
            </div>
          </div>
        </template>

        <!-- Facility type -->
        <template v-slot:item.facilityType="{ item }">
          <v-chip
            v-if="item.facilityType"
            x-small
            label
            color="indigo lighten-5"
            text-color="indigo darken-2"
          >
            {{ item.facilityType }}
          </v-chip>
          <span v-else class="hca-muted">—</span>
        </template>

        <!-- Status -->
        <template v-slot:item.status="{ item }">
          <div class="d-flex align-center" style="gap:5px">
            <span
              class="hca-status-dot"
              :class="
                item.status === 'active'
                  ? 'hca-status-dot--active'
                  : 'hca-status-dot--inactive'
              "
            ></span>
            <span
              :class="
                item.status === 'active'
                  ? 'hca-status--active'
                  : 'hca-status--inactive'
              "
            >
              {{ item.status || "—" }}
            </span>
          </div>
        </template>

        <!-- HR Officers — one row per assigned practitioner -->
        <template v-slot:item.hrName="{ item }">
          <div v-if="item.hrs && item.hrs.length" class="hca-hr-list">
            <div v-for="(hr, i) in item.hrs" :key="i" class="hca-hr-cell">
              <v-avatar
                size="22"
                color="blue lighten-4"
                class="mr-1 flex-shrink-0"
              >
                <span class="hca-initials indigo--text text--darken-3">
                  {{ getInitials(hr.hrName) }}
                </span>
              </v-avatar>
              <span class="hca-bold">{{ hr.hrName }}</span>
            </div>
          </div>
          <v-chip
            v-else
            x-small
            label
            color="red lighten-5"
            text-color="red darken-3"
          >
            <v-icon x-small left>mdi-alert-circle-outline</v-icon>
            No HR Assigned
          </v-chip>
        </template>

        <!-- HR Facilities -->
        <template v-slot:item.hrFacilityName="{ item }">
          <div v-if="item.hrs && item.hrs.length" class="hca-hr-list">
            <div v-for="(hr, i) in item.hrs" :key="i" class="hca-fac-row">
              <span
                :class="hr.hrFacilityId === item.facilityId ? 'hca-bold' : ''"
              >
                {{ hr.hrFacilityName || "—" }}
              </span>
              <v-chip
                v-if="hr.hrDistrictId && hr.hrDistrictId !== item.districtId"
                x-small
                label
                class="ml-1"
                color="amber lighten-4"
                text-color="amber darken-4"
              >
                <v-icon x-small left>mdi-swap-horizontal</v-icon>
                Cross-district
              </v-chip>
            </div>
          </div>
          <span v-else class="hca-muted">—</span>
        </template>

        <!-- Reports-to indicator -->
        <template v-slot:item.reportsTo="{ item }">
          <div v-if="item.reportsToFacilityName">
            <v-chip
              x-small
              label
              color="teal lighten-5"
              text-color="teal darken-2"
            >
              <v-icon x-small left>mdi-arrow-top-right</v-icon>
              {{ item.reportsToFacilityName }}
            </v-chip>
          </div>
          <span v-else class="hca-muted">—</span>
        </template>
      </v-data-table>
    </v-card>
    <br />
    <br />
    <br />
    <br />
  </div>
</template>

<script>
export default {
  name: "HrCoverageAudit",

  data() {
    return {
      loading: false,
      items: [],
      totalItems: 0,

      tableOptions: {
        page: 1,
        itemsPerPage: 20,
      },

      filters: {
        facilityName: null,
        hrFacilityId: null,
        type: null,
        status: null,
      },

      locationMenuOpen: false,
      locationTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {},
        loading: false,
        displayValue: "",
      },

      reportingtoFacilityMenuOpen: false,
      reportingtoFacilityTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {},
        loading: false,
        displayValue: "",
      },

      typeOptions: [],
      statusOptions: [
        { code: "active", display: "Active" },
        { code: "inactive", display: "Inactive" },
        { code: "suspended", display: "Suspended" },
      ],

      headers: [
        {
          text: "Facility",
          value: "facilityName",
          sortable: true,
          width: "22%",
        },
        { text: "Type", value: "facilityType", sortable: true, width: "10%" },
        { text: "Status", value: "status", sortable: true, width: "8%" },
        {
          text: "Reports To",
          value: "reportsTo",
          sortable: false,
          width: "14%",
        },
        { text: "HR Officers", value: "hrName", sortable: false, width: "18%" },
        {
          text: "HR Facility",
          value: "hrFacilityName",
          sortable: false,
          width: "18%",
        },
      ],

      fetchDebounce: null,
    };
  },

  computed: {
    activeFilterCount() {
      return [
        this.filters.facilityName,
        this.reportingtoFacilityTree.displayValue,
        this.filters.type,
        this.filters.status,
        this.locationTree.displayValue,
      ].filter(Boolean).length;
    },
  },

  watch: {
    tableOptions: {
      handler() {
        // Guard against the watcher firing during component initialisation
        // (Vuetify fills in sortBy/sortDesc/etc. on first render, which triggers
        // this deep watcher before mounted() has called fetchData).
        if (!this._fetchReady) return;
        this.fetchData();
      },
      deep: true,
    },
    "locationTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.locationTree.displayValue = id
        ? this.locationTree.treeLookup[id]?.name || id
        : "";
      this.locationMenuOpen = false;
      this.resetAndFetch();
    },
    "reportingtoFacilityTree.active"(val) {
      const id = val && val.length ? val[0] : null;
      this.filters.hrFacilityId = id ? id.split("/")[1] : null;
      this.reportingtoFacilityTree.displayValue = id
        ? (this.reportingtoFacilityTree.treeLookup[id] &&
            this.reportingtoFacilityTree.treeLookup[id].name) ||
          id
        : "";
      this.reportingtoFacilityMenuOpen = false;
      this.resetAndFetch();
    },
  },

  async mounted() {
    await Promise.all([
      this.loadLocationTree(),
      this.loadreportingtoFacilityTree(),
      this.loadTypeOptions(),
    ]);
    // Allow the tableOptions watcher to trigger fetches now that setup is done.
    // This flag prevents the watcher from firing a second concurrent fetch
    // during Vuetify's own initialisation of the options object above.
    this._fetchReady = true;
    await this.fetchData();
  },

  methods: {
    // ── Fetch main table data ───────────────────────────────────────────────
    async fetchData() {
      this.loading = true;
      try {
        const { page, itemsPerPage } = this.tableOptions;

        const fhirParams = new URLSearchParams({
          _profile: "http://ihris.org/fhir/StructureDefinition/ls-facility",
          _count: itemsPerPage,
          _total: "accurate",
          _offset: (page - 1) * itemsPerPage,
        });

        if (this.filters.status) fhirParams.set("status", this.filters.status);
        if (this.filters.type) fhirParams.set("type", this.filters.type);

        // Name search: FHIR supports name:contains
        if (this.filters.facilityName)
          fhirParams.set("name:contains", this.filters.facilityName);

        // HR facility filter: FHIR search param reportstofacility on the facility resource
        if (this.filters.hrFacilityId)
          fhirParams.set("reportstofacility", this.filters.hrFacilityId);

        // Location filter: scope to district, council, or exact facility via partof chain
        if (this.locationTree.active.length) {
          const id = this.locationTree.active[0];
          const info = this.locationTree.treeLookup[id];
          if (info?.type === "facility") {
            // exact facility — use _id
            fhirParams.set("_id", id.split("/")[1]);
          } else if (info?.type === "council") {
            // all facilities whose council = this council
            fhirParams.set("partof", id);
          } else {
            // district — facilities partOf a council that is partOf this district
            // FHIR supports chained partof: partof.partof
            fhirParams.set("partof.partof", id);
          }
        }

        const fhirRes = await fetch(`/fhir/Location?${fhirParams}`);
        const bundle = await fhirRes.json();

        // ── Step 2: Extract facilities from the bundle ────────────────────────
        // No _include in this fetch so every entry IS a facility — no profile
        // filter needed. Cast bundle.total to Number; some HAPI versions return
        // it as a string which would silently break Vuetify's page math.
        const facilities = (bundle.entry || []).map((e) => e.resource);
        this.totalItems = Number(bundle.total);

        // ── Step 3: Batch-resolve councils + districts for this page ──────────
        // Collect the unique council IDs referenced by this page's facilities,
        // then fetch them all in a single FHIR call. A single-hop _include
        // (not :iterate) is enough to also pull in their parent districts.
        const councilIds = [
          ...new Set(
            facilities
              .map((f) => f.partOf?.reference?.split("/")?.[1])
              .filter(Boolean),
          ),
        ];

        const resourceById = {};
        if (councilIds.length) {
          const locRes = await fetch(
            `/fhir/Location?_id=${councilIds.join(
              ",",
            )}&_include=Location:partof&_count=500`,
          );
          const locData = await locRes.json();
          for (const entry of locData.entry || []) {
            resourceById[entry.resource.id] = entry.resource;
          }
        }

        // ── Step 4: Enrich each facility with council + district names ─────────
        // facility.partOf → council,  council.partOf → district
        const enriched = facilities.map((fac) => {
          const councilId = fac.partOf?.reference?.split("/")?.[1];
          const council = councilId ? resourceById[councilId] : null;
          const districtId = council?.partOf?.reference?.split("/")?.[1];
          const district = districtId ? resourceById[districtId] : null;

          return {
            facilityId: fac.id,
            facilityName: fac.name,
            facilityType: fac.type?.[0]?.coding?.[0]?.display || null,
            status: fac.status,
            reportsToFacilityId:
              fac.extension
                ?.find(
                  (e) =>
                    e.url ===
                    "http://ihris.org/fhir/StructureDefinition/reports-to-facility",
                )
                ?.valueReference?.reference?.split("/")?.[1] || null,
            reportsToFacilityName: null, // resolved below if needed
            councilName: council?.name || "—",
            districtId: districtId || null,
            districtName: district?.name || "—",
            // HR fields filled in Step 5 — array, one entry per assigned HR
            hrs: [],
          };
        });

        // ── Step 5: Resolve all HRs for each facility in parallel ──────────────
        // getHR now returns an array where each entry has a practitioners[] array
        // (multiple HRs can be assigned to the same facility).
        await Promise.all(
          enriched.map(async (row) => {
            if (!row.districtId) return;
            try {
              const params = new URLSearchParams({
                district: row.districtId,
                facility: row.facilityId,
              });
              const res = await fetch(`/site/general/getHR?${params}`);
              const data = await res.json();
              if (!data || (Array.isArray(data) && !data.length)) return;

              // Resolve all HR entries — each entry covers one HR facility and
              // may list multiple practitioners assigned to that facility.
              const hrEntries = await Promise.all(
                data.map(async (hr) => {
                  // Resolve district of the HR facility for cross-district flag
                  let hrDistrictId = null;
                  if (hr.facility) {
                    const hrFac = resourceById[hr.facility];
                    if (hrFac) {
                      const hrCouncilId = hrFac.partOf?.reference?.split(
                        "/",
                      )?.[1];
                      const hrCouncil = hrCouncilId
                        ? resourceById[hrCouncilId]
                        : null;
                      hrDistrictId =
                        hrCouncil?.partOf?.reference?.split("/")?.[1] || null;
                    } else {
                      try {
                        const lRes = await fetch(
                          `/fhir/Location/${hr.facility}`,
                        );
                        const lData = await lRes.json();
                        const hrCouncilId = lData.partOf?.reference?.split(
                          "/",
                        )?.[1];
                        if (hrCouncilId) {
                          const cRes = await fetch(
                            `/fhir/Location/${hrCouncilId}`,
                          );
                          const cData = await cRes.json();
                          hrDistrictId =
                            cData.partOf?.reference?.split("/")?.[1] || null;
                        }
                      } catch (err) {
                        console.log(err);
                      }
                    }
                  }

                  // Resolve display names for all practitioners in this entry
                  const practitioners = Array.isArray(hr.practitioners)
                    ? hr.practitioners
                    : hr.practitioner
                    ? [hr.practitioner]
                    : [];

                  const names = await Promise.all(
                    practitioners.map(async (practId) => {
                      try {
                        const pRes = await fetch(
                          `/fhir/Practitioner/${practId}`,
                        );
                        const pData = await pRes.json();
                        return {
                          id: practId,
                          name: this.parsePractitionerName(pData),
                        };
                      } catch (_) {
                        return { id: practId, name: `Practitioner/${practId}` };
                      }
                    }),
                  );

                  return names.map((p) => ({
                    practitionerId: p.id,
                    hrName: p.name,
                    hrFacilityId: hr.facility || null,
                    hrFacilityName: hr.facilityname || null,
                    hrDistrictId,
                  }));
                }),
              );

              // Flatten: one item per (practitioner × HR-facility) combination
              row.hrs = hrEntries.flat();
            } catch (err) {
              console.error(
                `getHR failed for facility ${row.facilityId}:`,
                err,
              );
            }
          }),
        );

        this.items = enriched;
      } catch (err) {
        console.error("HrCoverageAudit fetchData error", err);
      } finally {
        this.loading = false;
      }
    },

    parsePractitionerName(resource) {
      if (!resource?.name?.length) return "";
      const nameObj = resource.name[0];
      const given = nameObj.given ? nameObj.given.join(" ") : "";
      const family = nameObj.family || "";
      return (given + " " + family).trim();
    },

    debouncedFetch() {
      clearTimeout(this.fetchDebounce);
      this.fetchDebounce = setTimeout(() => {
        if (this.tableOptions.page !== 1) {
          // Changing page triggers the tableOptions watcher → fetchData.
          // Do NOT also call fetchData() — that causes a double fetch.
          this.tableOptions.page = 1;
        } else {
          // Already on page 1: assigning the same value won't trigger the
          // watcher, so call fetchData directly.
          this.fetchData();
        }
      }, 350);
    },

    resetAndFetch() {
      if (this.tableOptions.page !== 1) {
        // Changing page triggers the tableOptions watcher → fetchData.
        this.tableOptions.page = 1;
      } else {
        this.fetchData();
      }
    },

    // ── HR Facility treeview (facility-only selection) ──────────────────────
    async loadreportingtoFacilityTree() {
      if (this.reportingtoFacilityTree.items.length) return;
      this.reportingtoFacilityTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => {
          const node = {
            id: "Location/" + e.resource.id,
            name: e.resource.name,
            children: [],
            disabled: true, // districts are not selectable
          };
          this.reportingtoFacilityTree.treeLookup[node.id] = {
            name: node.name,
            type: "district",
          };
          return node;
        });
        this.reportingtoFacilityTree.items = nodes;
      } catch (err) {
        console.error("loadreportingtoFacilityTree error", err);
      } finally {
        this.reportingtoFacilityTree.loading = false;
      }
    },

    fetchHrFacilityChildren(item) {
      var parentInfo = this.reportingtoFacilityTree.treeLookup[item.id];
      var childType =
        parentInfo && parentInfo.type === "district" ? "council" : "facility";
      return fetch("/fhir/Location?partof=" + item.id + "&_count=200")
        .then(function(r) {
          return r.json();
        })
        .then((data) => {
          var children = (data.entry || []).map((e) => {
            var node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
              disabled: childType === "council", // only facilities are selectable
            };
            if (childType === "council") node.children = [];
            this.reportingtoFacilityTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchHrFacilityChildren error", err));
    },

    clearreportingtoFacilityTree() {
      this.reportingtoFacilityTree.active = [];
      this.reportingtoFacilityTree.displayValue = "";
      this.filters.hrFacilityId = null;
      this.resetAndFetch();
    },

    reportingtoFacilityNodeIcon(id) {
      var info = this.reportingtoFacilityTree.treeLookup[id];
      var type = info && info.type;
      if (type === "district") return "mdi-map-marker-radius";
      if (type === "council") return "mdi-city";
      return "mdi-hospital-building";
    },

    reportingtoFacilityNodeColor(id) {
      var info = this.reportingtoFacilityTree.treeLookup[id];
      var type = info && info.type;
      if (type === "district") return "#1e40af";
      if (type === "council") return "#0e7490";
      return "#16a34a";
    },

    // ── Location treeview ───────────────────────────────────────────────────
    async loadLocationTree() {
      if (this.locationTree.items.length) return;
      this.locationTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => {
          const node = {
            id: "Location/" + e.resource.id,
            name: e.resource.name,
            children: [],
          };
          this.locationTree.treeLookup[node.id] = {
            name: node.name,
            type: "district",
          };
          return node;
        });
        this.locationTree.items = nodes;
      } catch (err) {
        console.error("loadLocationTree error", err);
      } finally {
        this.locationTree.loading = false;
      }
    },

    fetchLocationChildren(item) {
      const parentInfo = this.locationTree.treeLookup[item.id];
      const childType =
        parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = {
              id: "Location/" + e.resource.id,
              name: e.resource.name,
            };
            if (childType === "council") node.children = []; // councils expand further
            this.locationTree.treeLookup[node.id] = {
              name: node.name,
              type: childType,
            };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchLocationChildren error", err));
    },

    clearLocationTree() {
      this.locationTree.active = [];
      this.locationTree.displayValue = "";
      this.resetAndFetch();
    },

    clearAllFilters() {
      this.filters.facilityName = null;
      this.filters.hrFacilityId = null;
      this.filters.type = null;
      this.filters.status = null;
      this.reportingtoFacilityTree.active = [];
      this.reportingtoFacilityTree.displayValue = "";
      this.clearLocationTree();
    },

    // ── Facility type options from ValueSet ─────────────────────────────────
    async loadTypeOptions() {
      try {
        const res = await fetch(
          "/fhir/ValueSet/facility-type-valueset/$expand",
        );
        const data = await res.json();
        this.typeOptions = (data.expansion?.contains || []).map((c) => ({
          code: c.code,
          display: c.display,
        }));
      } catch (err) {
        console.error("loadTypeOptions error", err);
      }
    },

    getInitials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((w) => w[0].toUpperCase())
        .join("");
    },
  },
};
</script>

